text:
{
  "jobs": [
    {
      "text": "Работать в дороге с ноутбука и телефона, нужен постоянный интернет с возможностью раздачи",
      "quote": "Работаю в дороге — ноутбук всегда со мной, так что интернет нужен постоянно, причём чтобы и на телефон, и раздать на комп."
    },
    {
      "text": "Обеспечить связь с заказчиками во время поездки",
      "quote": "этот час был нервным, потому что я без карты города и без связи с заказчиками"
    },
    {
      "text": "Использовать интернет для навигации и связи в поездке",
      "quote": "я без карты города и без связи с заказчиками"
    },
    {
      "text": "Оплачивать услуги картой МИР или через СБП",
      "quote": "Все мои карты — МИР или СБП, а некоторые сервисы иностранные платёжки не принимают."
    },
    {
      "text": "Получать поддержку на русском языке",
      "quote": "поддержка на месте отвечает, и карты МИР проходили"
    },
    {
      "text": "Раздавать интернет на ноутбук без задержек",
      "quote": "раздавал на ноутбук без задержек"
    }
  ],
  "pains": [
    {
      "text": "Большой счёт за роуминг из-за фоновых обновлений и мессенджеров",
      "quote": "фоновые обновления и мессенджеры сожрали мегабайты, и мне прилетело сообщение о списании около 3 500 рублей сверх пакета"
    },
    {
      "text": "Невозможность дозвониться в техподдержку оператора",
      "quote": "В техподдержку дозвониться не мог, а когда дозвонился — сказали, что это тариф такой, мол, надо было другой подключать."
    },
    {
      "text": "eSIM может не сработать сразу на месте",
      "quote": "Самое тревожное — что eSIM может не сработать сразу на месте."
    },
    {
      "text": "Приходится искать вайфай и писать в поддержку при сбое",
      "quote": "Пришлось искать вайфай в кафе, писать в поддержку — они там что-то переконфигурировали, и через час заработало."
    },
    {
      "text": "Тарифы привязаны к одной стране, а поездка охватывает несколько стран",
      "quote": "у некоторых сервисов тарифы привязаны к одной стране, а я часто заезжаю в две за поездку — приходится покупать два пакета"
    },
    {
      "text": "Карты МИР принимают не везде",
      "quote": "карты МИР не везде проходят, это тоже напрягает"
    },
    {
      "text": "Отсутствие предупреждения о расходе и прозрачности от оператора",
      "quote": "Никакого предупреждения о расходе не было, никакого смс-уве[АДРЕС]что лимит заканчивается."
    },
    {
      "text": "Страх, что оператор молча спишет деньги",
      "quote": "не спишут ли деньги молча"
    },
    {
      "text": "Потеря времени при попытке оплаты картой, которая не принимается",
      "quote": "Потерял минут 20, но зато не пришлось потом мучиться."
    }
  ],
  "current_solutions": [
    {
      "text": "Покупка eSIM через приложения",
      "quote": "Обычно покупаю eSIM через приложения"
    },
    {
      "text": "Использование Airalo по совету коллеги",
      "quote": "Один коллега-дизайнер посоветовал Airalo — сказал, что он постоянно так делает в Азии и ни разу не было проблем."
    },
    {
      "text": "Отключение роуминга на физической симке перед вылетом",
      "quote": "Теперь я всегда перед вылетом захожу в настройки и отключаю роуминг на физической карте, чтобы случайно не активировалось."
    },
    {
      "text": "Поиск информации через гугл и телеграм-каналы",
      "quote": "Обычно просто гуглю в духе «лучшая eSIM для Турции 2024» или захожу в телеграм-каналы про путешествия."
    },
    {
      "text": "Проверка отзывов в магазине приложений",
      "quote": "смотрю отзывы в магазине приложений — если у сервиса рейтинг ниже 4,2 и много жалоб на поддержку, я не рискну"
    },
    {
      "text": "Опора на сарафан от знакомых фрилансеров",
      "quote": "Доверяю в основном сарафану от знакомых фрилансеров, которые тоже много мотаются"
    },
    {
      "text": "Покупка eSIM через приложение вместо физической симки",
      "quote": "просто купил eSIM через приложение за 10 долларов, установил за минуту, и пошёл по делам"
    }
  ],
  "barriers": [
    {
      "text": "Барьер доверия: негативный опыт с роумингом оператора",
      "quote": "у меня уже есть негативный опыт с их роумингом, я не уверен, что они не накрутят цену или не подключат какие-то скрытые услуги"
    },
    {
      "text": "Барьер понимания: неизвестно, можно ли раздавать интернет на ноутбук",
      "quote": "я не знаю, можно ли будет раздавать интернет на ноутбук — у некоторых операторов это запрещено в роуминге"
    },
    {
      "text": "Барьер оплаты: неизвестно, принимают ли карту МИР",
      "quote": "И главное: возьмут ли они карту МИР?"
    },
    {
      "text": "Барьер выбора: предпочтение остаться на сторонних сервисах до появления реальных отзывов",
      "quote": "скорее всего останусь на сторонних сервисах, пока не увижу реальные отзывы путешественников об этом тарифе"
    },
    {
      "text": "Барьер цены: если дороже в два раза, не будет брать",
      "quote": "Если оператор предложит такой же пакет, но в два раза дороже, чем у Airalo или другого независимого сервиса, я не буду брать."
    },
    {
      "text": "Барьер оплаты: если только Visa, то отпадает",
      "quote": "если только Visa, то я отпадаю"
    },
    {
      "text": "Барьер функциональности: раздача на ноутбук обязательна",
      "quote": "раздача на ноутбук должна работать, без этого я не могу"
    },
    {
      "text": "Барьер оплаты: сервисы, не принимающие МИР или СБП, не рассматриваются",
      "quote": "если сервис не берёт МИР или СБП — я его даже не рассматриваю"
    }
  ],
  "triggers": [
    {
      "text": "Большой счёт за роуминг в Турции",
      "quote": "пришёл счёт на несколько тысяч, хотя я почти не звонил"
    },
    {
      "text": "Случай, когда телефон сам потянул данные и оператор списал деньги",
      "quote": "прилетел, а телефон сам потянул какие-то данные, и оператор списал деньги за считанные минуты"
    },
    {
      "text": "Совет коллеги-фрилансера попробовать Airalo",
      "quote": "Один коллега-дизайнер посоветовал Airalo — сказал, что он постоянно так делает в Азии и ни разу не было проблем."
    },
    {
      "text": "Необходимость работать в дороге",
      "quote": "Работаю в дороге — ноутбук всегда со мной, так что интернет нужен постоянно"
    },
    {
      "text": "Отказ от физической симки из-за заморочек",
      "quote": "нужно было идти с ним в какой-то салон, регистрировать паспорт, ждать активации часа два. Я сразу отказался"
    }
  ],
  "words": [
    "обжёгся",
    "прилетело сообщение о списании",
    "не прикасаюсь",
    "взлетело с первого раза",
    "раздавал на ноутбук",
    "стоп-фактор",
    "отпадаю",
    "замороченным",
    "не повелся",
    "сарафан",
    "прозрачность",
    "отключить в один клик"
  ],
  "surprises": [
    "Респондент готов платить чуть больше за гарантию работы и поддержку на русском, несмотря на важность цены",
    "Негативный опыт с оператором настолько силён, что перевешивает удобство «всё в одном приложении»",
    "Респондент отказывается от дешёвой физической симки из-за необходимости регистрации паспорта и ожидания",
    "Респондент проверяет рейтинг сервиса в магазине приложений и не рискует, если рейтинг ниже 4,2"
  ]
}
